/*
 * Arabic (ar) catalog: English pivot key -> Arabic text.
 *
 * Loaded on demand by `src/core/i18n.js` when this is the active locale, so a
 * user downloads their own language and no other. Any key absent here renders
 * as its English source rather than as a placeholder.
 *
 * Keys with `${…}` are interpolation patterns: keep every placeholder, in an
 * order that reads naturally in Arabic — the engine re-splices the captured
 * values positionally.
 */

