  "An address of mine ({z}/{x}/{y})": "عنوان خاص بي ({z}/{x}/{y})",
  "An air conditioner from May to September, radiators from October to April: outside those months the card does not appear. No month lit means all year. A unit that is on always shows, even out of season.":
    "مكيّف من مايو إلى سبتمبر، والمشعّات من أكتوبر إلى أبريل: خارج تلك الأشهر لا تظهر البطاقة. عدم إضاءة أي شهر يعني طوال السنة. الوحدة المشتعلة تظهر دائمًا، حتى خارج الموسم.",
  "An alarm_control_panel.* entity: the page reads the arming modes it accepts from it and sends the commands to it.":
    "كيان alarm_control_panel.*: تقرأ منه الصفحة أوضاع التسليح التي يقبلها وترسل إليه الأوامر.",
  "An emoji or an mdi: icon. Tap the box beside it to pick one from the load catalogue.":
    "رمز تعبيري أو أيقونة mdi:. انقر على المربع المجاور لاختيار واحدة من فهرس الأحمال.",
  "An entity that can open is required: ${domini}.": "مطلوب كيان قادر على الفتح: ${domini}.",
