  "Earthquakes · Weather · Lightning · Pollen · Flights": "زلازل · طقس · صواعق · لقاح · رحلات",
  "Earthquakes, civil protection warnings, lightning, pollen, thermal comfort and flights overhead: for each one pick the sensor its integration already brought into Home Assistant. No field is required and each one is enough on its own: the page shows only the sources you have. The dashboard calls no service, it reads what is there.":
    "الزلازل وتحذيرات الحماية المدنية والصواعق وحبوب اللقاح والراحة الحرارية والطائرات في السماء: لكل منها اختر المستشعر الذي أدخله تكامله في Home Assistant. لا حقل إلزامي وكل واحد يكفي وحده: تعرض الصفحة المصادر التي لديك فقط. اللوحة لا تستدعي أي خدمة، بل تقرأ ما هو موجود.",
