  Good: "جيد",
  "Good up to the first, fair up to the second, poor up to the third, bad beyond. The defaults are the norms: the European index bands for particulates and gases, EN 16798-1 for CO₂, the WHO guidelines for monoxide. Change them only if you know why.":
    "جيّد حتى الأول، مقبول حتى الثاني، رديء حتى الثالث، وسيّئ بعد ذلك. القيم الافتراضية هي المعايير: نطاقات المؤشر الأوروبي للجسيمات والغازات، وEN 16798-1 لثاني أكسيد الكربون، وإرشادات منظمة الصحة العالمية لأول أكسيد الكربون. لا تغيّرها إلا إذا كنت تعرف السبب.",
