  Home: "المنزل",
  "Home (fallback)": "المنزل (بديل)",
  "Home Assistant declares no machine and no network piece.":
    "لا يُعلن Home Assistant عن أي جهاز أو قطعة شبكة.",
  "Home Assistant declares the air sensors itself — particulates, CO₂, monoxide, volatile compounds — and the tile appears on its own. Here you correct that: drop a sensor that should not count, add one that is not found, and move the boundaries between good, fair, poor and bad.":
    "يعلن Home Assistant عن مستشعرات الهواء بنفسه — الجسيمات وثاني أكسيد الكربون وأول أكسيد الكربون والمركبات المتطايرة — وتظهر البطاقة تلقائيًا. هنا تصحّح ذلك: استبعد مستشعرًا لا ينبغي احتسابه، وأضف مستشعرًا لم يُعثر عليه، وحرّك الحدود بين جيّد ومقبول ورديء وسيّئ.",
  "Home Assistant did not take the scheduled switch-off: update the integration and try again.":
    "لم يستلم Home Assistant الإطفاء المجدول: حدِّث التكامل وأعد المحاولة.",
  "Home Assistant does not allow you to command this entity: it needs a user with permission, or the entity is exposed read-only.":
    "لا يسمح لك Home Assistant بالتحكم في هذا الكيان: يلزم مستخدم لديه الصلاحية، أو أن الكيان معروض للقراءة فقط.",
  "Home Assistant entity": "كيان Home Assistant",
  "Home Assistant entity for the new light": "كيان Home Assistant للضوء الجديد",
  "Home Assistant entity, e.g.": "كيان Home Assistant، مثلًا",
  "Home Assistant history is unavailable for the selected period.":
    "سجل Home Assistant غير متاح للفترة المحدَّدة.",
  "Home Assistant integrations, official or from HACS, with the devices they bring. Pick the bowl, the litter box or the collar: the card's fields fill themselves in.":
    "تكاملات Home Assistant، الرسمية أو من HACS، مع الأجهزة التي تجلبها. اختر الوعاء أو صندوق الرمل أو الطوق: حقول البطاقة تُملأ من تلقاء نفسها.",
  "Home Assistant integrations, official or from HACS, with the devices they bring. Pick the device: the fields come along by themselves.":
    "تكاملات Home Assistant، الرسمية أو من HACS، مع الأجهزة التي تجلبها. اختر الجهاز: تُملأ الحقول من تلقاء نفسها.",
  "Home Assistant integrations, official or from HACS, with the devices they bring. Pick the node: status, CPU, memory, disk and degrees come along by themselves.":
    "تكاملات Home Assistant، الرسمية أو من HACS، مع الأجهزة التي تأتي بها. اختر العقدة: الحالة والمعالج والذاكرة والقرص والدرجات تدخل من تلقاء نفسها.",
  "Home Assistant integrations, official or from HACS, with the devices they bring. Pick your TV or speaker: its entity, the controls the integration publishes next to it and its readings come along by themselves.":
    "تكاملات Home Assistant، الرسمية أو من HACS، مع الأجهزة التي تأتي بها. اختر تلفازك أو سمّاعتك: كيانه وأزرار التحكم التي ينشرها التكامل بجانبه وقراءاته تدخل من تلقاء نفسها.",
  "Home Assistant integrations, official or from HACS, with the devices they bring. Pick your appliance: every entity comes along, and the card fields fill themselves in.":
    "تكاملات Home Assistant، الرسمية أو من HACS، مع الأجهزة التي تجلبها. اختر جهازك: تأتي كل الكيانات معه، وتُملأ حقول البطاقة من تلقاء نفسها.",
  "Home Assistant integrations, official or from HACS, with the devices they bring. Pick your car: battery or tank, range, odometer, doors and the rest come along by themselves.":
    "تكاملات Home Assistant، الرسمية أو من HACS، مع الأجهزة التي تجلبها. اختر سيارتك: البطارية أو الخزان، المدى، عداد المسافة، الأبواب والباقي تدخل من تلقاء نفسها.",
  "Home Assistant integrations, official or from HACS, with the devices they bring. Pick your robot: its entity, its maps, the battery, its programs and its readings come along by themselves.":
    "تكاملات Home Assistant، الرسمية أو من HACS، مع الأجهزة التي تأتي بها. اختر روبوتك: كيانه وخرائطه وبطاريته وبرامجه وقراءاته تدخل من تلقاء نفسها.",
  "Home Assistant is not answering": "Home Assistant لا يستجيب",
  "Home Assistant is not connected": "Home Assistant غير متصل",
  "Home Assistant keeps the countdown: you can close the dashboard and the unit still switches off.":
    "العدّ التنازلي يتولاه Home Assistant: يمكنك إغلاق اللوحة وستنطفئ الوحدة على أي حال.",
  "Home Assistant language": "لغة Home Assistant",
  "Home Assistant media folders": "مجلدات وسائط Home Assistant",
  "Home Assistant refused the target": "رفض Home Assistant الهدف",
  "Home Assistant to-do lists: tick them off from the Home tile and from the Agenda section, and the ones with a due date show up on the day they are due.":
    "قوائم مهام Home Assistant: تُشطب من بطاقة الصفحة الرئيسية ومن قسم «جدول الأعمال»، وما له تاريخ استحقاق يظهر في اليوم الذي يستحق فيه.",
  "Home Assistant version": "إصدار Home Assistant",
  "Home Assistant water heater": "سخان Home Assistant",
  "Home Assistant · Core system": "Home Assistant · النظام الأساسي",
  "Home Assistant's Recorder took too long to answer. That happens when the history is large or the server is small: it retries on its own, and if it keeps happening it is worth lowering the days the Recorder keeps (purge_keep_days) or excluding entities you do not need.":
    "استغرق Recorder في Home Assistant وقتًا طويلًا للرد. يحدث ذلك عندما يكون السجل كبيرًا أو الخادم صغيرًا: يعيد المحاولة من تلقاء نفسه، وإذا تكرر الأمر فمن الأفضل تقليل الأيام التي يحتفظ بها Recorder (purge_keep_days) أو استبعاد الكيانات غير اللازمة.",
