  House: "المنزل",
  "How it looks": "كيف تبدو",
  "How long it stays on": "كم تبقى مشتعلة",
  "How long it stays on from the moment you switch it on. Home Assistant keeps the countdown, not this page: you can close the dashboard and the unit still switches off. On the card you can change it every time.":
    "كم تبقى مشتعلة من لحظة تشغيلها. العدّ التنازلي يتولاه Home Assistant وليس هذه الصفحة: يمكنك إغلاق اللوحة وستنطفئ الوحدة على أي حال. على البطاقة يمكن تغييره في كل مرة.",
  "How many days are left before replacing it. Below the threshold the card says so, and the button below resets the count once you have changed it.":
    "كم يومًا بقي قبل الاستبدال. تحت الحد تقولها البطاقة، والزر أسفلها يصفّر العدّ بعد التغيير.",
  "How much food is left in the feeder. As a percentage the card draws a bar; a sensor saying “Low” or “Empty” counts the same, and below the threshold the card warns.":
    "كم بقي من الطعام في الموزّع. بالنسبة المئوية ترسم البطاقة شريطًا؛ والمستشعر الذي يقول «Low» أو «Empty» يُحسب مثله، وتحت العتبة تنبّه البطاقة.",
  "How much light means open (lux)": "كم من الضوء يعني أنه مفتوح (لوكس)",
  "How to read the Energy configuration": "كيف تُقرأ إعدادات الطاقة",
  Hue: "درجة اللون",
  Humidex: "مؤشر الرطوبة",
  "Humidex (optional)": "مؤشر الرطوبة (اختياري)",
  Humidity: "الرطوبة",
  "Humidity entity": "كيان الرطوبة",
  "Humidity name": "اسم الرطوبة",
  "Humidity sensor": "مستشعر الرطوبة",
  "Hybrid car": "سيارة هجينة",
  "Hyundai, Tesla, Renault, BMW… pick the device and the car arrives ready-made: battery or tank, range, odometer, doors and the rest. Or, below, one field at a time.":
    "Hyundai وTesla وRenault وBMW… اختر الجهاز وتصل السيارة جاهزة: البطارية أو الخزان، المدى، عداد المسافة، الأبواب والباقي. أو بالأسفل، حقلاً حقلاً.",
  "I cannot manage": "لا أستطيع",
  "I cannot read the entities from Home Assistant. Check the connection and try again.":
    "تعذّرت قراءة الكيانات من Home Assistant. تحقّق من الاتصال ثم أعد المحاولة.",
  "I could not read the queue:": "تعذّرت قراءة القائمة:",
  "I do not know": "لا أعرف",
  "I do not know where home is: Home Assistant did not answer. Pick a zone or write the coordinates.":
    "لا أعرف أين المنزل: لم يجب Home Assistant. اختر منطقة أو اكتب الإحداثيات.",
  "I would like it to": "أودّ أن",
  "I'll take it": "سأتولّاه",
  "IKEA's Vallhorn, a Zigbee contact on the flap, a light sensor… pick the mailbox device and whichever fields that integration publishes fill themselves in. One sensor alone is enough too.":
    "‏Vallhorn من إيكيا، أو تماس Zigbee، أو حساس ضوء… اختر الجهاز الموجود داخل صندوق البريد ويُملأ الحقلان من تلقاء نفسهما. يكفي مستشعر واحد أيضًا.",
  INSTANT: "لحظي",
  Icon: "الأيقونة",
  "Icon (e.g. ⚠️ 💧 🌡️)": "أيقونة (مثل ⚠️ 💧 🌡️)",
  "Icon (optional)": "أيقونة (اختياري)",
  "Ideal moisture max (%)": "الرطوبة المثالية القصوى (%)",
  "Ideal moisture min (%)": "الرطوبة المثالية الدنيا (%)",
  Ideas: "أفكار",
  Idle: "خامل",
  "If below (%)": "إذا كانت أقل من (%)",
  "If the collections live in one place, put it here: a calendar.* with one event per collection, or a sensor.* carrying the list of upcoming collections in its attributes. Each entry becomes a row, with the material guessed from its name.":
    "إذا كانت مواعيد الجمع في مكان واحد، ضعه هنا: تقويم calendar.* بحدث لكل موعد، أو حسّاس sensor.* يحمل قائمة المواعيد القادمة في خصائصه. يصبح كل عنصر سطرًا، مع استنتاج المادة من اسمه.",
  "If the panel splits the house into areas — day zone and night zone, house and workshop — add the second one here: the one you have now moves into the list exactly as it is, and the page grows a row to switch between them, each with its own state.":
    "إن كانت اللوحة تقسم البيت إلى مناطق — منطقة نهارية وأخرى ليلية، بيت وورشة — أضف الثانية هنا: التي لديك تنتقل إلى القائمة كما هي، ويظهر في الصفحة صفٌّ للتنقل بينها، لكلٍّ حالتها.",
  "If you have one, this is enough: it declares state, temperature and target itself.":
    "إذا كان لديك واحد، فهذا يكفي: يعلن هو نفسه الحالة ودرجة الحرارة والهدف.",
  "If you have two solar plants — two roofs, two tanks — add the second one here: the one you have now moves into the list exactly as it is, and the page grows a row to switch between them.":
    "إن كانت لديك منظومتان شمسيتان — سطحان، خزّانان — أضف الثانية هنا: التي لديك الآن تنتقل إلى القائمة كما هي، وتظهر في الصفحة صفٌّ للتنقل بينهما.",
  "If you run go2rtc or Frigate, put this line under “streams:” in their file:":
    "إن كنت تستخدم go2rtc أو Frigate فضع هذا السطر تحت «streams:» في ملفهما:",
