  "On/off · Consumption · Room by room": "تشغيل/إيقاف · الاستهلاك · غرفة بغرفة",
  "One bin per material, and for each the sensor that says when the collection comes: the page answers the evening question — what do I put out tonight — and the Home tile lights up the day before. Whoever has a single calendar, with one event per collection, puts it in the box at the bottom.":
    "حاوية لكل مادة، ولكل منها المستشعر الذي يقول متى يأتي الجمع: تجيب الصفحة عن سؤال المساء — ماذا أُخرج الليلة — وتضيء بطاقة الرئيسية في اليوم السابق. من لديه تقويم واحد، بحدث لكل عملية جمع، يضعه في المربع في الأسفل.",
  "One room at a time · Scenes · Sensors": "غرفة واحدة في كل مرة · مشاهد · مستشعرات",
  "One single tile": "بطاقة واحدة فقط",
  "One step, and you will never be asked again: open github.com/login/device and type this code.":
    "خطوة واحدة فقط، ولن يُطلب منك ذلك مرة أخرى: افتح github.com/login/device وأدخل هذا الرمز.",
  "One tile per plant": "واحدة لكل منظومة",
  "One window can carry all three: fill in the boxes you have, the box tells the type.":
    "النافذة الواحدة قد تجمع الثلاثة معًا: املأ الخانات المتوفّرة لديك، والخانة نفسها تحدّد النوع.",
  "Only daily sensors or Recorder deltas from cumulative total meters are counted. Lifetime values are never added directly.":
    "تُحتسب فقط الحساسات اليومية أو فروق Recorder من العدّادات التراكمية. ولا تُجمع القيم التراكمية مباشرة أبدًا.",
  "Only if you already have a helper measuring the period. Without one, the period comes from the total meter.":
    "فقط إن كان لديك helper يقيس الفترة. وبدونه تأتي الفترة من العدّاد الإجمالي.",
  "Only needed when the shutter is driven by two relays — one that sends it up, one that sends it down — like a Shelly left in switch mode: then “Close” switches this one on, and “Stop” switches both off. With a real cover.* leave it empty.":
    "مطلوب فقط عندما تُدار الستارة بمرحّلين — واحد يرفعها وآخر ينزلها — مثل جهاز Shelly المتروك في وضع المفتاح: عندها يشغّل زر «إغلاق» هذا المرحّل، ويطفئ زر «إيقاف» كليهما. مع كيان cover.* حقيقي اتركه فارغًا.",
  "Only rooms containing a light are shown. Edit opens all light fields, not a browser prompt. The pills say what each light can do — RGB, tunable white, dimmer or plain on/off — and that is what drives the controls in the popup.":
    "تُعرض فقط الغرف التي تحتوي على ضوء. «تعديل» يفتح كل حقول الضوء، لا نافذة المتصفح. وتوضّح الشارات ما يستطيعه كل ضوء — RGB أو أبيض قابل للضبط أو مُخفِّت أو تشغيل/إطفاء فقط — وعلى ذلك تعتمد عناصر التحكم في النافذة.",
  "Only the modes the panel actually accepts are listed. Removing one hides it from the section and changes nothing about what the panel can do; disarm always stays.":
    "تظهر هنا الأوضاع التي تقبلها لوحة الإنذار فعلياً فقط. إزالة أحدها يخفيه من القسم ولا يغيّر شيئاً مما تستطيع اللوحة فعله؛ ويبقى إلغاء التفعيل دائماً.",
  "Only with the soil below (%)": "فقط عندما تكون التربة أقل من (%)",
  Open: "مفتوحة",
  "Open (as before)": "افتح (كما كان)",
  "Open the menu": "افتح القائمة",
  "⚪ Empty section — add an entity below to show it": "⚪ قسم فارغ — أضف كيانًا أدناه لإظهاره",
  "You haven't saved": "لم تقم بالحفظ",
  "You entered entities in this section without saving them. If you leave now, they will be lost.":
    "أدخلت كيانات في هذا القسم دون حفظها. إذا خرجت الآن فستُفقد.",
  "Save and continue": "حفظ ومتابعة",
  "Leave without saving": "الخروج دون حفظ",
  "Stay here": "البقاء هنا",
  "Nobody home": "لا أحد في المنزل",
  "Big buttons: a dashboard action or any entity (a scene, a script, a button). For each one the name on the tablet, the line below and the drawing.":
    "أزرار كبيرة: إجراء من اللوحة أو أي كيان (مشهد، سكربت، زر). لكل منها الاسم على الجهاز اللوحي والسطر أسفله والرسم.",
  "Full config": "الإعداد الكامل",
  "On, a light added to the room in the source dashboard shows up by itself. Off, the slots are chosen here: any entity or action, with the name and drawing you want.":
    "عند التشغيل، يظهر تلقائيًا أي ضوء يُضاف إلى الغرفة في اللوحة المصدر. عند الإيقاف، تُختار الأماكن هنا: أي كيان أو إجراء، بالاسم والرسم اللذين تريدهما.",
  "Slots of your own: in each one any Home Assistant entity — a light, a socket, a lock, a sensor — or a dashboard action, with the name and drawing you want.":
    "أماكن خاصة بك تمامًا: في كل منها أي كيان من Home Assistant — ضوء، مقبس، قفل، مستشعر — أو إجراء من اللوحة، بالاسم والرسم اللذين تريدهما.",
  "A dehumidifier is not a thermostat: pick its humidifier entity and the Climate page gives it a card of its own, with the current humidity, the target, the modes, the fan and the tank-full warning. The other fields fill themselves in when you save.":
    "مزيل الرطوبة ليس منظم حرارة: اختر كيان humidifier الخاص به وستمنحه صفحة المناخ بطاقة خاصة به، مع الرطوبة الحالية والهدف والأوضاع والمروحة وتنبيه امتلاء الخزان. تمتلئ الحقول الأخرى تلقائيًا عند الحفظ.",
  "Add a dehumidifier": "إضافة مزيل رطوبة",
