  "Shutter opening": "الستارة المعدنية قيد الفتح",
  Shutters: "الستائر",
  "Shutters and curtains show up on the 🪟 Windows page, grouped by floor and room. Every row accepts a cover.* entity — with position and percentages — or a switch.* relay: one when switching it on keeps the shutter up, two when one relay sends it up and another sends it down, like a Shelly in switch mode. When the window opens by hand — shutters, blinds, a handle — leave the command boxes empty and fill in the contact sensor alone: the card still draws it and says whether it is open.":
    "تظهر الستائر والمصاريع في صفحة 🪟 النوافذ، مجمَّعة حسب الطابق والغرفة. يقبل كل صف كيان cover.* — بالموضع والنِّسب — أو مُرحِّل switch.*: واحد إذا كان تشغيله يُبقي المصراع مرفوعًا، واثنان إذا كان أحدهما يرفع والآخر يخفض، مثل جهاز Shelly في وضع المفتاح. وإذا كانت النافذة تُفتح باليد — مصاريع أو شيش أو مقبض — فاترك خانات الأوامر فارغة واملأ مستشعر الفتح وحده: تُرسَم البطاقة كالمعتاد وتقول ما إذا كانت مفتوحة.",
  "Shutters · Curtains · Contact sensors": "الستائر المعدنية · الستائر القماشية · مستشعرات الفتح",
  "Sign path timeout": "انتهت مهلة توقيع المسار",
  "Simple alternative to the duration entity.": "بديل بسيط لكيان المدة.",
