  "Single calendar or sensor (optional)": "تقويم أو حسّاس واحد (اختياري)",
  "Skin tone": "لون البشرة",
  "Skip detection →": "تخطَّ الاكتشاف ←",
  "Skip the program if ≥ (%)": "تخطَّ البرنامج إذا كان ≥ (%)",
  Slate: "إردواز",
  "Slight discomfort": "انزعاج خفيف",
  "Slightly cool": "بارد قليلًا",
  "Slightly warm": "دافئ قليلًا",
  "Small pool": "مسبح صغير",
  "Smart thermostats publish the heating mode on a separate entity: TADO has Home and Away, others add Holiday or Boost. The card shows it, and if the entity is a select or an input_select you can change it right there.":
    "الترموستات الذكية تنشر وضع التدفئة في كيان منفصل: TADO لديه في المنزل وخارج المنزل، وغيره يضيف إجازة أو Boost. البطاقة تعرضه، وإذا كان الكيان select أو input_select يمكنك تغييره من هناك مباشرة.",
  "SmartThings, Sonos, Chromecast, AirPlay… pick the device and the player arrives ready-made: its entity, the controls the integration publishes next to it — a TV's power switch, the input dropdown — and its readings. Or, below, one field at a time.":
    "‏SmartThings وSonos وChromecast وAirPlay… اختر الجهاز ويصل المشغّل جاهزًا: كيانه وأزرار التحكم المنشورة بجانبه — مفتاح تشغيل التلفاز، قائمة المصدر — وقراءاته. أو، في الأسفل، خانة خانة.",
