  "Turn everything on": "أضئ كل شيء",
  "Turn it off to open on the first tap: whoever opens their own front door ten times a day knows the confirmation by heart. A PIN is not a confirmation and stays: a protected door keeps asking for it.":
    "أطفئه لتفتح من أول لمسة: من يفتح بابه عشر مرات في اليوم يحفظ التأكيد عن ظهر قلب. رمز PIN ليس تأكيدًا ويبقى: الباب المحمي يظل يطلبه.",
  "Turn off": "إطفاء",
  "Turn on": "تشغيل",
  "Turn on or off": "تشغيل أو إطفاء",
  "Turn on/off": "تشغيل/إطفاء",
  "Turn the boiler on or off": "تشغيل المرجل أو إطفاؤه",
  "Turning them on and off": "التشغيل والإطفاء",
  Tuxedo: "بدلة سهرة",
  "Two shots of the same car: the dashboard shows the plugged-in one while it charges and the other one the rest of the time. The first is enough — without the second it simply stays.":
    "صورتان للسيارة نفسها: تعرض اللوحة صورة السيارة الموصولة أثناء الشحن، والأخرى في بقية الوقت. وتكفي الأولى — فمن دون الثانية تبقى هي الظاهرة ببساطة.",
  "Two weeks that repeat, written by hand: tap a day and pick what goes out. No sensor and no Home Assistant calendar needed — the page and the Home tile read this exactly as they would read an integration. A material that already has its own sensor above is not repeated: the sensor wins.":
    "أسبوعان يتكرران، مكتوبان يدويًا: المس يومًا واختر ما يخرج. لا حاجة إلى أي مستشعر ولا إلى تقويم Home Assistant — الصفحة وبطاقة الرئيسية تقرآن هذا تمامًا كما تقرآن أي تكامل. المادة التي لها مستشعر أعلاه لا تتكرر: المستشعر هو الذي يحكم.",
  Type: "النوع",
  "Type / artwork": "النوع / الرسم",
  "Type at least two letters: it searches every tab at once.":
    "اكتب حرفين على الأقل: يبحث في كل التبويبات معًا.",
