  "WebRTC: skipped — fill in “go2rtc stream name” in the Cameras tab (the camera name is not the lever)":
    "WebRTC: تم التخطي — املأ «اسم بث go2rtc» في تبويب الكاميرات (اسم الكاميرا ليس هو المفتاح)",
