  Waiting: "تنتظر",
  "watered just now": "سُقيت للتو",
  "When the soil is dry but the home weather forecasts rain in the next hours, the plant waits instead of asking for water. Only for those the rain really reaches.":
    "عندما تكون التربة جافة لكن طقس المنزل يتوقع مطرًا في الساعات القادمة، تنتظر النبتة بدلًا من طلب الماء. فقط للنباتات التي يصلها المطر فعلًا.",
