  "No battery pack configured": "لم تُضبط أي حزمة بطاريات",
  "No cells found": "لم يُعثر على خلايا",
  "No pack answering": "لا تستجيب أي حزمة",
  "No reading": "لا توجد قراءة",
  "One cell voltage per line, in cell order. You can paste them all at once, commas work too; “Find the cells” takes them from Home Assistant using the prefix of the pack's other entities.":
    "جهد خلية واحد في كل سطر، بترتيب الخلايا. يمكنك لصقها كلها دفعة واحدة، حتى مفصولة بفواصل؛ «ابحث عن الخلايا» يأخذها من Home Assistant ببادئة كيانات الحزمة الأخرى.",
  "Optional: if the BMS does not publish it, the imbalance is worked out from the cells.":
    "اختياري: إذا لم ينشره نظام BMS، يُحسب عدم التوازن من الخلايا.",
