  "Positive when charging (JK, JBD, Daly)": "موجب أثناء الشحن (JK وJBD وDaly)",
  "Negative when charging": "سالب أثناء الشحن",
  "With the sign the BMS uses: if it writes it negative while charging, pick that in “Current sign”.":
    "بالإشارة التي يستخدمها نظام إدارة البطارية: إذا كتبه سالبًا أثناء الشحن فاختر ذلك في «إشارة التيار».",
  "If the page says “Discharging” while the battery is charging, your BMS writes the current the other way round: pick “Negative when charging”.":
    "إذا عرضت الصفحة «تفريغ» بينما البطارية تُشحن، فإن نظام إدارة البطارية يكتب التيار بالعكس: اختر «سالب أثناء الشحن».",
  "Remaining energy": "الطاقة المتبقية",
  "Save pack": "حفظ الحزمة",
  "State of charge (SoC)": "حالة الشحن (SoC)",
  "State of health (SoH)": "حالة الصحة (SoH)",
  "Take the ${quanti} packs Home Assistant found":
    "خذ الحزم التي وجدها Home Assistant وعددها ${quanti}",
  "The pack's charge percentage: without it the pack does not show.":
    "نسبة شحن الحزمة: من دونها لا تظهر الحزمة.",
  "The storage packs and their BMS: they show in the Batteries tab of Energy and on the Battery storage tile in Home. One pack per row: its entity is the state of charge, and inside are the others — health, voltages, currents, temperatures, cycles, capacity and every single cell.":
    "حزم التخزين وأنظمة BMS الخاصة بها: تظهر في تبويب البطاريات في الطاقة وفي بطاقة تخزين البطاريات في الرئيسية. حزمة واحدة في كل صف: كيانها هو حالة الشحن، وفي داخلها البقية — الصحة، الجهود، التيارات، درجات الحرارة، الدورات، السعة وكل خلية على حدة.",
  "to the house": "نحو المنزل",
  "Unit of a hand-written capacity": "وحدة السعة المكتوبة يدويًا",
  "Unnamed pack": "حزمة بلا اسم",
  "Until you pick the state of charge this pack is nowhere: not in Energy, not on the Home tile.":
    "إلى أن تختار حالة الشحن لن تظهر هذه الحزمة في أي مكان: لا في الطاقة ولا في بطاقة الرئيسية.",
  "When the highest and lowest cells are further apart than this, the pack says “Needs balancing” and the Home tile asks for attention.":
    "عندما تتباعد أعلى خلية وأدنى خلية أكثر من هذا، تقول الحزمة «تحتاج إلى موازنة» وتطلب بطاقة الرئيسية الانتباه.",
  "${accese} of ${totale} lights on": "${accese} من ${totale} أضواء مضاءة",
  "${lettura.posizione}% open": "مفتوحة بنسبة ${lettura.posizione}%",
  "1 of ${totale} lights on": "1 من ${totale} أضواء مضاء",
  "Everything with its own control, in a grid": "كل شيء مع تحكمه الخاص، في شبكة",
  "How an open room looks on the Rooms page.": "كيف تبدو الغرفة المفتوحة في صفحة الغرف.",
  "Room view": "عرض الغرفة",
  "the light is off": "الضوء مطفأ",
  "the light is on": "الضوء مضاء",
  "The list split by type, as before": "القائمة مقسمة حسب النوع، كما في السابق",
