  "Also on: ${nomi}": "يعمل أيضًا: ${nomi}",
  "at ${ora}": "عند ${ora}",
  "Buttons in Cooking": "أزرار في الطهي",
  "Cooking — status, times, temperature and controls": "الطهي — الحالة والأوقات والحرارة والتحكم",
  "Cooking shows up once the appliances include an air fryer, an oven, a microwave, a cooktop or a hood.":
    "يظهر الطهي عندما يكون بين الأجهزة قلاية هوائية أو فرن أو ميكروويف أو موقد أو شفّاط.",
  "Cooking status": "حالة الطهي",
