  "🦎 The terrarium's entities": "🦎 كيانات التيراريوم",
  "🧽 Cleaning": "🧽 التنظيف",
  "🪣 The tank": "🪣 الحوض",
  Aquariums: "أحواض السمك",
  "Aquariums and terrariums": "أحواض السمك والتيراريوم",
