  "Humidity too high": "الرطوبة مرتفعة جدًا",
  "Humidity too low": "الرطوبة منخفضة جدًا",
  "Last cleaning": "آخر تنظيف",
  Mister: "جهاز الرذاذ",
  "Not recorded yet: tap “Done today” on the day you clean it, and from then on the card counts the days.":
    "لم يُسجَّل بعد: اضغط «تم اليوم» في اليوم الذي تنظّفه فيه، ومن ذلك الحين تحسب البطاقة الأيام.",
  "One row per entity: temperature and pH with their ideal range, the water level, the lights, the filter and the heater. Empty ranges use the defaults: 24–27 °C and pH 6.5–7.5.":
    "صف لكل كيان: الحرارة ودرجة الحموضة مع نطاقهما المثالي، ومستوى الماء، والأضواء، والفلتر، والسخان. النطاقات الفارغة تأخذ القيم الافتراضية: 24–27 °C ودرجة حموضة 6.5–7.5.",
  "One row per entity: warm-side and cool-side temperatures, humidity, lights, heat lamp, UVB, mister. Empty ranges use the defaults: 28–35 °C on the warm side, 22–28 °C on the cool side, humidity 40–80 %.":
    "صف لكل كيان: حرارة الجانب الدافئ والجانب البارد، والرطوبة، والأضواء، والمصباح الحراري، وUVB، وجهاز الرذاذ. النطاقات الفارغة تأخذ القيم الافتراضية: 28–35 °C في الجانب الدافئ، و22–28 °C في الجانب البارد، ورطوبة 40–80 %.",
  "Optional: left empty, the terrarium reminds nobody to clean it. With a number the card says when it is due.":
    "اختياري: إن تُرك فارغًا لا يذكّر التيراريوم أحدًا بتنظيفه. ومع رقم تقول البطاقة متى يحين الوقت.",
  "Other pet": "حيوان آخر",
  "Other pets": "حيوانات أخرى",
  "Other reading": "قياس آخر",
  "Reservoir level": "مستوى الخزان",
  "Take the ${quante} terrarium entities Home Assistant found":
    "خُذ كيانات التيراريوم الـ ${quante} التي وجدها Home Assistant",
  "Temperature (cool side)": "الحرارة (الجانب البارد)",
  "Temperature (warm side)": "الحرارة (الجانب الدافئ)",
  Terrarium: "تيراريوم",
  "Terrarium climate": "مناخ التيراريوم",
  Terrariums: "التيراريوم",
  "The pets of the house: one card each, with its photo and what concerns it — the bowl, the litter box, the water, the microchip door, the collar. Aquariums and terrariums too, as many as you have: each with its own entities.":
    "حيوانات البيت: لكل واحد بطاقة، بصورته وبكل ما يخصّه — الوعاء وصندوق الرمل والماء والباب ذي الشريحة والطوق. وأحواض السمك والتيراريوم أيضًا، بقدر ما لديك: لكلٍّ كياناته.",
