  "Front door": "الباب الأمامي",
  "It fills itself with every light of the source dashboard: a light added there shows up here too.":
    "تمتلئ تلقائيًا بكل أضواء اللوحة المصدر: أي ضوء يُضاف هناك يظهر هنا أيضًا.",
  "My page": "صفحتي",
  "None yet": "لا شيء بعد",
  "Nothing to show here": "لا شيء لعرضه هنا",
  "on the tablet": "على الجهاز اللوحي",
  "or an action": "أو إجراء",
  "Second button name": "اسم الزر الثاني",
  "The page takes its temperature and suggested controls from here":
    "تأخذ الصفحة من هنا درجة الحرارة وعناصر التحكم المقترحة",
  "Your own controls": "عناصر التحكم الخاصة بك",
  "Heating · Cooling": "تدفئة · تبريد",
  "It fills itself with the source dashboard's climate, split into the Cooling and Heating tabs like the Climate section: air conditioners in cooling, radiators and thermostats in heating, heat pumps in both.":
    "تمتلئ تلقائيًا بأجهزة المناخ في اللوحة المصدر، مقسّمة إلى تبويبي التبريد والتدفئة كما في قسم المناخ: المكيفات في التبريد، والمشعات ومنظمات الحرارة في التدفئة، والمضخات الحرارية في الاثنين.",
  "Opens on": "يفتح على",
  "Page type": "نوع الصفحة",
  "Shown on the tab at the top": "يظهر على علامة التبويب في الأعلى",
  "The wall tablet's panel. Choose the pages — the tabs at the top — and what each one holds. On the tablet, holding the clock for two seconds brings you back here.":
    "لوحة الجهاز اللوحي الجداري. اختر الصفحات — علامات التبويب في الأعلى — وما تحتويه كل منها. على الجهاز اللوحي، الضغط مطولًا على الساعة لثانيتين يعيدك إلى هنا.",
  "All blinds": "كل الستائر",
  "At the top and on the rest screen. Empty: the first one Home Assistant has":
    "في الأعلى وعلى شاشة الراحة. فارغ: الأول الموجود في Home Assistant",
  Blinds: "الستائر",
  "Choose the readings in the config": "اختر القراءات في الإعدادات",
  Duplicate: "تكرار",
  "Duplicate page": "تكرار الصفحة",
  "Empty: the one of the first page's room": "فارغ: مستشعر غرفة الصفحة الأولى",
  "Every blind in the house": "كل ستائر المنزل",
  "from the dashboard": "من اللوحة",
  "From the grid": "من الشبكة",
  "Grid exchange": "التبادل مع الشبكة",
  "House consumption": "استهلاك المنزل",
  "House uses": "يستهلك المنزل",
  "How many cards on screen; the rest scroll": "كم بطاقة على الشاشة؛ الباقي يتمرر",
  "How many slots, and how big. In portrait columns and rows swap":
    "كم خانة وبأي حجم. في الوضع العمودي تتبادل الأعمدة والصفوف",
  "It fills itself with every blind of the source dashboard: up, stop and down for each one.":
    "تمتلئ تلقائيًا بكل ستائر اللوحة المصدر: رفع وإيقاف وخفض لكل واحدة.",
