  "The alarm has been triggered.": "تم إطلاق الإنذار.",
  "The alarm is going off": "الإنذار يرنّ",
  "the car": "السيارة",
  "The house assistant watches the house for you and tells you the most important thing to do right now: lights left on in an empty house, a window open with the heating on, rain on its way, the laundry done, spare solar power. It learns from what you dismiss, and remembers it for the whole household. On a computer or tablet it sits to the right of the people, on a phone below them.":
    "يراقب مساعد المنزل البيت نيابةً عنك ويخبرك بأهم ما يجب فعله الآن: أضواء مضاءة في منزل فارغ، نافذة مفتوحة والتدفئة تعمل، مطر قادم، غسيل انتهى، طاقة شمسية فائضة. يتعلم مما ترفضه ويتذكره لكل أفراد المنزل. على الكمبيوتر والجهاز اللوحي يظهر على يمين الأشخاص، وعلى الهاتف تحتهم.",
  "The house is drawing ${kw} kW from the grid": "المنزل يسحب ${kw} كيلوواط من الشبكة",
  "The house is empty and ${nomi(aperte, l)} is unlocked":
    "المنزل فارغ و${nomi(aperte, l)} غير مقفلة",
  "The leak sensor is wet: shall I close the valve?": "حساس التسرب مبلل: هل أغلق الصمام؟",
  "The leak sensor is wet.": "حساس التسرب مبلل.",
  "There are ${quanti} updates to install": "هناك ${quanti} تحديثات للتثبيت",
  "There is an update to install": "هناك تحديث للتثبيت",
  Tonight: "هذا المساء",
  "Turn it off until someone is back?": "هل أطفئه حتى يعود أحد؟",
  "Turn it off?": "هل أطفئه؟",
  "Turn off climate": "أطفئ التكييف",
  "Turn them off?": "هل أطفئها؟",
  urgent: "عاجل",
  "Water detected: ${nomi(bagnati, l)}": "تم اكتشاف ماء: ${nomi(bagnati, l)}",
  "What it talks about": "عمّ يتحدث",
  "Worth a check.": "يستحق التحقق.",
  "You left with ${nomi(aperte, l)} open": "خرجتم و${nomi(aperte, l)} مفتوحة",
  "You're near the limit: can ${nomi(accesi, l)} wait?":
    "أنت قريب من الحد: هل يمكن لـ${nomi(accesi, l)} الانتظار؟",
  "You're near the meter's limit.": "أنت قريب من حد العداد.",
  "You're out and ${g.name} is open": "أنتم خارج المنزل و${g.name} مفتوح",
  "e.g. 30": "مثلاً 30",
  "End-of-cycle delay under ${minuti} minutes: 0 W pauses mid-programme look like the end of the cycle.":
    "تأخير نهاية الدورة أقل من ${minuti} دقيقة: التوقفات عند 0 واط في منتصف البرنامج تبدو كأنها نهاية الدورة.",
  "Recommended: running ${a} W, standby ${b} W, delay ${minuti} min.":
    "الموصى به: تشغيل ${a} واط، استعداد ${b} واط، تأخير ${minuti} د.",
  "Running threshold under 1 W: a lit display is enough to show Running.":
    "عتبة التشغيل أقل من 1 واط: تكفي الشاشة المضاءة لإظهار «قيد التشغيل».",
  "Standby threshold at or above the running one: standby can never show.":
    "عتبة الاستعداد مساوية لعتبة التشغيل أو أعلى: لا يمكن أن يظهر الاستعداد أبداً.",
  "Use the recommended values": "استخدم القيم الموصى بها",
  "With these values one cycle can turn into many mini-cycles.":
    "بهذه القيم قد تتحول دورة واحدة إلى دورات صغيرة كثيرة.",
  "System off": "النظام متوقف",
  "Battery power": "قدرة البطارية",
