  "Battery: power": "البطارية: القدرة",
  "Big live numbers. Left empty, they come from the source dashboard's Energy section, with its direction.":
    "أرقام كبيرة مباشرة. إن تُركت فارغة تؤخذ من قسم الطاقة في اللوحة المصدر، باتجاهها.",
  "Charging power": "قدرة الشحن",
