  "Flip the sign": "اعكس الإشارة",
  "Grid: how you measure it": "الشبكة: كيف تقيسها",
  "If your inverter writes them the other way round: grid positive when feeding in, battery positive when charging":
    "إذا كان العاكس يكتبها بالعكس: الشبكة موجبة عند التصدير، والبطارية موجبة عند الشحن",
