  "The entity that says the alarm is going off: a switch, a sensor or a helper. When it reads “triggered” Security, the Home tile and the wall panel turn red, and the house sends the urgent notification.": "الكيان الذي يفيد بأن الإنذار انطلق: مفتاح أو مستشعر أو مساعد. عندما تكون قيمته «منطلق» يتحول الأمان وبطاقة الرئيسية ولوحة الحائط إلى الأحمر ويرسل المنزل الإشعار العاجل.",
