  "Each plant has its own meter and its own limit: above the threshold the alert says which plant. The one you had before now belongs to the first plant.": "لكل منظومة عدادها وحدّها: فوق العتبة يذكر التنبيه أيّ منظومة. العتبة السابقة صارت للمنظومة الأولى.",
