  "The house appliances become per-room circles in the flow. Each one goes in its meter's flow: until you say which, it shows up in none.": "تصبح أجهزة البيت في التدفق دوائر حسب الغرفة. كلٌّ يذهب إلى تدفق عداده: ما لم تحدده لا يظهر في أيٍّ منها.",
